using Microsoft.AspNetCore.DataProtection;
using System.Text.Json;
namespace HomeLibrary;
public sealed record InsightInput(string Kind,string CopyId="");
public sealed record InsightSettings(bool Enabled,bool Clear=false,string Confirmation="");
// Aggregate counts only. No visitor/session identifiers, IPs, URLs, query strings or search terms.
public sealed class LibraryInsights {
 readonly object gate=new();readonly string file;readonly IDataProtector protector;readonly bool collect;Data saved;string readError="";
 public sealed class Data {public bool Enabled{get;set;}public string Since{get;set;}="";public Dictionary<string,long> Totals{get;set;}=[];public Dictionary<string,Day> Days{get;set;}=[];public Dictionary<string,long> Popular{get;set;}=[];}
 public sealed class Day {public Dictionary<string,long> Counts{get;set;}=[];public Dictionary<string,long> Popular{get;set;}=[];}
 static readonly HashSet<string> kinds=["visits","catalogViews","bookViews","searches","zeroResults","requests","checkouts","returns","catalogAdded"];
 public LibraryInsights(string directory,IDataProtectionProvider provider,bool collect=true){this.collect=collect;file=Path.Combine(directory,"library-insights.protected");protector=provider.CreateProtector("Carribrary.LibraryInsights.v1");saved=new();try{if(File.Exists(file)){if(new FileInfo(file).Length>128*1024*1024)throw new LibraryError("Oversized analytics storage.");saved=JsonSerializer.Deserialize<Data>(protector.Unprotect(File.ReadAllBytes(file)),Library.Json)??new();}}catch(Exception e)when(e is IOException or UnauthorizedAccessException or System.Security.Cryptography.CryptographicException or JsonException or LibraryError){saved=new();readError="Stored analytics could not be read. Library operations remain available. Restore a complete backup or explicitly clear analytics to reset only these counts.";}}

 void Save(){var tmp=file+".tmp";File.WriteAllBytes(tmp,protector.Protect(JsonSerializer.SerializeToUtf8Bytes(saved,Library.Json)));if(!OperatingSystem.IsWindows())File.SetUnixFileMode(tmp,UnixFileMode.UserRead|UnixFileMode.UserWrite);File.Move(tmp,file,true);}
 static void Add(Dictionary<string,long> values,string key,long n){if(n>0)values[key]=Math.Min(1000000000000,values.GetValueOrDefault(key)+Math.Min(n,1000000));}
 public void Change(InsightSettings input){lock(gate){if(readError!=""&&!input.Clear)throw new LibraryError(readError);if(input.Clear){if(input.Confirmation!="CLEAR ANALYTICS")throw new LibraryError("Type CLEAR ANALYTICS exactly.");saved=new(){Enabled=input.Enabled};readError="";}saved.Enabled=input.Enabled;if(saved.Enabled&&saved.Since=="")saved.Since=DateTimeOffset.UtcNow.ToString("O");Save();}}
 public void Record(string kind,long count=1,string copyUid="",DateOnly? date=null){lock(gate){if(!collect||readError!=""||!saved.Enabled||!kinds.Contains(kind)||count<=0)return;var day=(date??DateOnly.FromDateTime(DateTime.UtcNow)).ToString("yyyy-MM-dd");if(!saved.Days.TryGetValue(day,out var bucket))saved.Days[day]=bucket=new();Add(bucket.Counts,kind,count);Add(saved.Totals,kind,count);
  if(kind=="bookViews"&&Guid.TryParseExact(copyUid,"N",out _)){if(bucket.Popular.ContainsKey(copyUid)||bucket.Popular.Count<1000)Add(bucket.Popular,copyUid,count);if(saved.Popular.ContainsKey(copyUid)||saved.Popular.Count<10000)Add(saved.Popular,copyUid,count);}
  foreach(var old in saved.Days.Keys.OrderByDescending(x=>x,StringComparer.Ordinal).Skip(730).ToArray())saved.Days.Remove(old);Save();}}
 public void Observe(LibraryState before,LibraryState after){
  try{Record("catalogAdded",after.Books.Count(b=>!before.Books.Any(x=>x.CopyUid==b.CopyUid)));Record("requests",after.Requests.Count(r=>!before.Requests.Any(x=>x.Id==r.Id)));Record("checkouts",after.Loans.Count(l=>!before.Loans.Any(x=>x.Id==l.Id)));Record("returns",after.Loans.Count(l=>l.ReturnedDate!=null&&before.Loans.Any(x=>x.Id==l.Id&&x.ReturnedDate==null)));}catch(IOException){}catch(UnauthorizedAccessException){} // Analytics cannot undo a committed loan.
 }
 public object Report(string range,LibraryState state){lock(gate){if(range is not ("7" or "30" or "90" or "all"))throw new LibraryError("Choose 7, 30, 90 days or all time.");var since=range=="all"?"":DateOnly.FromDateTime(DateTime.UtcNow).AddDays(1-int.Parse(range)).ToString("yyyy-MM-dd");var days=saved.Days.Where(x=>since==""||string.CompareOrdinal(x.Key,since)>=0).OrderBy(x=>x.Key).ToArray();var counts=range=="all"?new(saved.Totals):kinds.ToDictionary(k=>k,k=>days.Sum(d=>d.Value.Counts.GetValueOrDefault(k)));var popular=range=="all"?saved.Popular:days.SelectMany(d=>d.Value.Popular).GroupBy(x=>x.Key).ToDictionary(g=>g.Key,g=>g.Sum(x=>x.Value));return new{saved.Enabled,saved.Since,error=readError,collectionPausedForRecovery=!collect,range,counts,daily=days.Select(d=>new{date=d.Key,counts=d.Value.Counts}),popular=popular.OrderByDescending(p=>p.Value).Take(10).Select(p=>new{title=state.Books.Find(b=>b.CopyUid==p.Key)?.Title??"Removed book",views=p.Value}),catalogSize=state.Books.Count(b=>!b.Archived),dailyRetention=730};}}
 public static void Map(WebApplication app,Settings settings,Store store,Func<HttpContext,bool> admin,Func<HttpContext,bool> mobile){
  foreach(var prefix in new[]{"/api","/mobile"}){
   app.MapGet(prefix+"/insights",(string? range,HttpContext c,LibraryInsights insights)=>(prefix=="/api"?admin(c):mobile(c))?Results.Json(insights.Report(range??"30",store.Read().State),Library.Json):Results.NotFound());
   app.MapPost(prefix+"/insights",(InsightSettings input,HttpContext c,LibraryInsights insights)=>{if(!(prefix=="/api"?admin(c):mobile(c)))return Results.NotFound();insights.Change(input);return Results.Ok(new{saved=true});});
  }
  void Track(InsightInput input,LibraryInsights insights){if(input.Kind is not ("catalogViews" or "searches" or "zeroResults" or "bookViews"))throw new LibraryError("Unsupported aggregate event.");var book=input.Kind=="bookViews"?store.Read().State.Books.Find(b=>!b.Archived&&b.Id==input.CopyId):null;if(input.Kind=="bookViews"&&book==null)throw new LibraryError("Book unavailable.",404);insights.Record(input.Kind,1,book?.CopyUid??"");}
  app.MapPost("/s/{token}/insights",(string token,InsightInput input,HttpContext c,Sharing sharing,LibraryInsights insights)=>{if(c.Connection.LocalPort!=settings.CatalogPort||!sharing.Allowed(token))return Results.NotFound();if(c.Request.Headers["DNT"]!="1"&&c.Request.Headers["Sec-GPC"]!="1")Track(input,insights);return Results.NoContent();}).RequireRateLimiting("personal-reading");
  app.MapPost("/account/insights",(InsightInput input,HttpContext c,BorrowerAccounts accounts,LibraryInsights insights)=>{if(c.Connection.LocalPort!=settings.CatalogPort)return Results.NotFound();var account=AccountEndpoints.Account(c,accounts);BorrowerAccounts.ApprovedReader(account,store);if(c.Request.Headers["DNT"]!="1"&&c.Request.Headers["Sec-GPC"]!="1")Track(input,insights);return Results.NoContent();}).RequireRateLimiting("personal-reading");
 }
}
